		Host:       host,
		Port:       portI,
		User:       config.RouteToDatabase.Username,
		Database:   config.RouteToDatabase.Database,
		Encryption: msdsn.EncryptionDisabled,
		Protocols:  []string{"tcp"},
	}, nil)

