        attempt={attempt}
        diagnosis={diagnosis}
        canTestConnection={canTestConnection}
        testConnection={() => testConnection(makeTestConnRequest())}
        stepNumber={2}
        stepDescription="Verify that your database is accessible"
      />
      <StyledBox>
        <Text bold mb={3}>
          To Access your Database
        </Text>
        <Box mb={2}>
          Log into your Teleport cluster
          <TextSelectCopy
            mt="1"
            text={generateTshLoginCommand({
              authType,
              username,
              clusterId,
            })}
          />
        </Box>
        <Box mb={2}>
          Connect to your database
          <TextSelectCopy mt="1" text={tshDbCmd} />
        </Box>
      </StyledBox>
      <ActionButtons onProceed={nextStep} lastStep={true} />
    </Box>
  );
}

const StyledBox = styled(Box)`
  max-width: 800px;
  background-color: ${props => props.theme.colors.spotBackground[0]};
  border-radius: 8px;
  padding: 20px;
`;

